insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('tac_ahogado_recurso', 'tactica', 'opcion', 2, 1140, 1200, 'Si vas claramente perdiendo, ¿qué recurso táctico defensivo puede salvar la partida?', '["Buscar el ahogado del rey rival, que da tablas","Ofrecer tablas una y otra vez hasta que acepte","Capturar la dama rival al precio que sea","Enrocar en el último momento posible"]'::jsonb, null, 0, null, null, 'Aun en posiciones perdidas se puede maniobrar hacia una trampa de ahogado: dejar al rey rival sin ninguna jugada legal y sin estar en jaque. Medio punto de la nada.', null, null),
  ('tac_tactica_vs_estrategia', 'tactica', 'opcion', 1, 900, 950, '¿Qué es una «táctica» en ajedrez, a diferencia de la «estrategia»?', '["Jugadas forzadas y cortas para ganar algo concreto","Un plan de largo plazo, sin ninguna jugada forzada","Otro nombre con el que se llama a la apertura","Un tipo particular de final de peones"]'::jsonb, null, 0, null, null, 'La táctica es corto plazo y forzada: capturas, jaques, amenazas que el rival tiene que atender. La estrategia es el plan de fondo — qué casillas ocupar, qué estructura buscar. Las dos hacen falta, pero en estos niveles la táctica decide casi todas las partidas.', null, null),
  ('mate_rey_captura_defendida', 'mate', 'opcion', 1, 650, 700, '¿Puede un rey capturar una pieza rival que está defendida por otra pieza?', '["No: quedaría en jaque tras la captura","Sí, mientras la defendida no sea la dama","Sí, sin ninguna excepción posible","Solo en la primera jugada de la partida"]'::jsonb, null, 0, null, null, 'El rey nunca puede ir a una casilla atacada, así que capturar una pieza defendida sería ilegal. De ahí sale media técnica de mate: basta con que la pieza que da jaque esté defendida.', null, null),
  ('mate_pasillo_cuando', 'mate', 'opcion', 1, 720, 950, 'El «mate del pasillo» ocurre típicamente cuando…', '["Sus propios peones encierran al rey en la última fila","El rey está en el centro del tablero, sin peones cerca","Se acaba de hacer el enroque largo por el flanco","Al rival no le queda ningún peón en el tablero"]'::jsonb, null, 0, null, null, 'El rey enrocado queda atrapado detrás de sus tres peones, y una torre o la dama entran a la última fila con jaque. No hay dónde ir, ni quién capture o bloquee.', null, null),
  ('mate_pasillo_torre_a', 'mate', 'opcion_tablero', 1, 840, 950, 'Juegan las blancas. ¿Cuál de estas jugadas de la torre da jaque mate?', '["Ta8#","Ta7","Tf1","Rg2"]'::jsonb, '6k1/5ppp/8/8/8/8/8/R5K1 w - - 0 1', 0, null, null, 'Ta8 es mate: el rey negro, encerrado por sus peones de f7, g7 y h7, no tiene casilla libre y nadie puede capturar la torre ni meterse en medio.', null, null),
  ('mate_coz_cuando', 'mate', 'opcion', 2, 1310, 1200, 'El «mate de la coz» suele darse cuando…', '["Un caballo da jaque de cerca y nadie puede huir","Intervienen solamente los dos alfiles del bando","Un peón corona a dama y da mate de inmediato","El rey rival se quedó totalmente solo en el tablero"]'::jsonb, null, 0, null, null, 'El caballo da el jaque final desde muy cerca, y el rey no lo puede capturar porque está defendido o porque sus propias piezas le tapan todas las salidas. Es el mate más vistoso del ajedrez.', null, null),
  ('mate_tecnica_torre_franja', 'mate', 'opcion', 1, 940, 1200, 'En el final de rey y torre contra rey solo, ¿cuál es la técnica básica para forzar el mate?', '["Encerrarlo en una franja cada vez más chica","Dar jaques sin parar hasta que salga el mate solo","Cambiar la torre por el rey rival y después coronar","Avanzar los peones propios lo más rápido posible"]'::jsonb, null, 0, null, null, 'La torre le corta una fila o una columna y el propio rey se acerca a empujarlo; la franja se achica hasta el borde. Sin el rey propio, la torre sola no da mate nunca.', null, null),
  ('mate_dama_ahogado', 'mate', 'opcion', 1, 1040, 1200, 'En el final de rey y dama contra rey solo, ¿qué error hay que evitar con más cuidado?', '["Ahogar al rey rival sin querer, y dar tablas","Alejar demasiado la dama del propio rey negro","Enrocar antes de haber dado el mate final","Capturar el rey rival en vez de dar mate"]'::jsonb, null, 0, null, null, 'Con dama de sobra, el único peligro real es apretar tanto que el rey rival quede sin jaque y sin jugada legal. La regla práctica: antes de cada jugada, comprobar que le queda al menos una casilla.', null, null),
  ('mate_legal', 'mate', 'opcion', 2, 1290, 1450, 'El «mate de Légal» es una trampa clásica de apertura en la que las blancas…', '["Entregan la dama porque ya tienen el mate listo","Ganan la dama rival sin dar nada a cambio","Obligan al rival a enrocar cuando no le conviene","Evitan cualquier sacrificio durante la apertura"]'::jsonb, null, 0, null, null, 'Se entrega la dama a propósito porque unas jugadas después hay mate forzado con caballo y alfil. Es la trampa que enseña que el material no manda cuando hay mate.', null, null),
  ('mate_opera', 'mate', 'opcion', 3, 1640, 1450, 'El «mate de la Ópera», famoso por una partida de Paul Morphy, combina típicamente…', '["Dama y otra pieza rematando por la última fila","Solamente los dos caballos del bando atacante","Un final de peones puros, sin ninguna pieza","Un sacrificio de calidad en el flanco de dama"]'::jsonb, null, 0, null, null, 'Morphy remató con dama y torre mientras el rival tenía las piezas sin desarrollar, estorbando su propia defensa. Es la partida que mejor enseña para qué sirve desarrollar.', null, null),
  ('mate_objetivo_final', 'mate', 'opcion', 1, 470, 700, '¿Cuál es el objetivo final de cualquier partida de ajedrez?', '["Dar jaque mate al rey rival","Capturar todas las piezas del rival","Coronar la mayor cantidad de peones","Terminar con más tiempo en el reloj"]'::jsonb, null, 0, null, null, 'Muchas partidas terminan por abandono, por tablas o por tiempo, pero el objetivo formal sigue siendo uno solo: el jaque mate. Todo lo demás son caminos hacia eso.', null, null),
  ('mate_patrones_memoria', 'mate', 'opcion', 1, 720, 950, '¿Por qué conviene memorizar los patrones de mate típicos?', '["Para reconocerlos rápido en vez de calcular de cero","Porque son las únicas formas legales de dar un mate","Porque el reglamento exige saberlos de memoria","Porque sin conocerlos no se puede enrocar"]'::jsonb, null, 0, null, null, 'Quien ya vio el patrón no calcula: lo reconoce y va directo a la jugada que lo completa. Es la diferencia entre encontrar el mate en dos segundos o no encontrarlo.', null, null),
  ('mate_rey_al_borde', 'mate', 'opcion', 1, 750, 950, 'En casi todos los mates con poco material, ¿dónde suele terminar acorralado el rey rival?', '["En el borde o una esquina del tablero","Justo en el centro exacto del tablero","Siempre de vuelta en su casilla inicial","En cualquier lado: da igual dónde esté"]'::jsonb, null, 0, null, null, 'En el centro el rey tiene ocho casillas; en el borde, cinco; en una esquina, tres. Por eso toda la técnica de mate consiste en empujarlo hacia afuera.', null, null),
  ('mate_evitar_ahogado', 'mate', 'opcion', 1, 850, 950, 'Al dar mate con mucho material de ventaja, ¿qué error común hay que evitar con cuidado?', '["Dejarlo sin jaque y sin jugadas: es ahogado","Dar demasiados jaques seguidos, uno tras otro","Mover el propio rey con demasiada frecuencia","Coronar un peón más de los que hacen falta"]'::jsonb, null, 0, null, null, 'Con ventaja aplastante es fácil encerrar al rey rival por descuido, y el ahogado convierte una victoria segura en medio punto. Es la forma más dolorosa de no ganar una partida ganada.', null, null),
  ('mate_dos_torres_cuidado', 'mate', 'opcion', 1, 980, 1200, 'Al dar mate con dos torres contra el rey solo, ¿qué cuidado hay que tener con la torre que da el jaque final?', '["Que quede fuera del alcance del rey rival","Ponerla siempre en la primera fila del tablero","Entregarla justo antes de dar el mate final","Tenerla lo más lejos posible del rey propio"]'::jsonb, null, 0, null, null, 'Si la torre que da jaque queda pegada al rey y sin defensa, el rey la captura y no hay mate. Con dos torres alcanza con darle jaque desde lejos, alternando filas.', null, null),
  ('mate_rey_participa', 'mate', 'opcion', 1, 1020, 950, 'En los finales de mate con poco material, ¿qué pieza propia hay que acercar para completar el mate?', '["El propio rey, que tiene que participar","La dama, que siempre alcanza ella sola","Los peones que queden en el tablero","Ninguna: las piezas mayores alcanzan"]'::jsonb, null, 0, null, null, 'Salvo con dama o con dos torres, casi todos los mates básicos necesitan al rey propio empujando. Es el cambio de mentalidad del final: el rey deja de esconderse y sale a trabajar.', null, null),
  ('mate_antes_que_material', 'mate', 'opcion', 1, 780, 950, '¿Por qué dar jaque mate es preferible a seguir ganando material, cuando las dos cosas están disponibles?', '["Porque el mate termina la partida ahí mismo","Porque ganar más material está prohibido","Porque el material no vale nada en ajedrez","Porque dar mate suma puntos extra al resultado"]'::jsonb, null, 0, null, null, 'El resultado no depende de cuánto material se junte sino de si hay mate. Quedarse acumulando piezas con el mate a la vista es la forma más común de dejar escapar una partida ganada.', null, null),
  ('mate_luft', 'mate', 'opcion', 1, 870, 950, '¿Cómo se puede prevenir un futuro mate del pasillo antes de que sea un problema?', '["Haciendo un respiradero: adelantar un peón del rey","Cambiando todas las piezas mayores que uno tiene","Evitando enrocar durante toda la partida entera","Retrasando el desarrollo de todas las piezas"]'::jsonb, null, 0, null, null, 'Se llama «luft» —aire, en alemán—: se adelanta h3 o g3 para que el rey tenga por dónde salir. Cuesta un tiempo y evita perder la partida de un jaque.', null, null),
  ('mate_dos_alfiles_esquina', 'mate', 'opcion', 2, 1200, 1450, 'Al forzar mate con rey y dos alfiles contra rey solo, ¿en qué esquina se puede completar el mate?', '["En cualquiera: cubren casillas de los dos colores","Solo en la del color de uno de los dos alfiles","En ninguna: ese final siempre termina en tablas","Solo si además queda algún peón en el tablero"]'::jsonb, null, 0, null, null, 'Entre los dos alfiles controlan casillas claras y oscuras, así que ninguna esquina es segura para el rey. Es más fácil de lo que parece: hay que llevarlo al borde con el rey propio y cerrar las diagonales.', null, null),
  ('mate_alfil_caballo_esquina', 'mate', 'opcion', 2, 1210, 1700, 'El final de rey, alfil y caballo contra rey solo tiene una particularidad conocida: el mate solo se puede forzar…', '["En la esquina del color de casillas del alfil","En cualquier esquina, sin ninguna restricción","Únicamente en el centro mismo del tablero","Solo si el rival comete algún error grave"]'::jsonb, null, 0, null, null, 'El alfil solo controla un color, así que en la esquina del color contrario el rey defensor se escapa. Hay que empujarlo hasta la esquina correcta, y eso puede llevar más de treinta jugadas: es el mate básico más difícil.', null, null),
  ('mate_basicos_cuales', 'mate', 'opcion', 1, 1090, 1200, '¿Cuáles son los finales de mate «básicos» que conviene dominar de memoria desde el principio?', '["Dama contra rey, torre contra rey y dos alfiles","Solamente el final de rey y peón contra el rey","Únicamente los finales con más de dos torres","Ninguno: todos los mates se improvisan jugando"]'::jsonb, null, 0, null, null, 'Son los tres que aparecen de verdad y que se pueden forzar siempre. Saberlos de memoria ahorra tiempo de reloj y, sobre todo, evita el ahogado por nervios.', null, null),
  ('fin_oposicion_concepto', 'finales', 'opcion', 2, 1190, 950, 'En un final de rey y peón contra rey, el concepto de «oposición» significa que…', '["Con una casilla de por medio, gana quien NO mueve","El rey puede atacar al rey rival, solo en finales","Los peones se oponen en una misma columna","Es otro nombre para la regla del cuadrado"]'::jsonb, null, 0, null, null, 'Cuando los reyes quedan frente a frente con una casilla vacía en medio, el que tiene que mover es el que pierde terreno: está obligado a apartarse. Por eso en los finales de peones vale más el turno que la posición.', null, null),
  ('fin_oposicion_tablero', 'finales', 'opcion_tablero', 2, 1330, 1200, 'Juegan las blancas, con los reyes enfrentados y una casilla de por medio. ¿Quién tiene la oposición?', '["Las negras: las blancas tienen que ceder","Las blancas, que llevan la iniciativa","Nadie: acá el concepto no se aplica","Depende de qué peón quede en el tablero"]'::jsonb, '4k3/8/4K3/8/8/8/8/8 w - - 0 1', 0, null, null, 'Tiene la oposición quien NO está obligado a mover. Como juegan las blancas, cualquier jugada de su rey le cede terreno al negro.', null, null),
  ('fin_cuadrado_para_que', 'finales', 'opcion', 1, 740, 950, 'La «regla del cuadrado» sirve para saber rápidamente si…', '["El rey alcanza a tiempo a un peón pasado","Un caballo llega a una casilla concreta","Una posición es tablas por repetición","Un enroque todavía es legal o ya no"]'::jsonb, null, 0, null, null, 'Se dibuja mentalmente el cuadrado que va del peón a su casilla de coronación: si el rey defensor puede entrar en él, lo alcanza. Ahorra calcular la carrera jugada por jugada.', null, null),
  ('fin_zugzwang', 'finales', 'opcion', 2, 1360, 1200, '¿Qué es el «zugzwang» en ajedrez?', '["Estar obligado a mover y que toda jugada empeore","Una apertura poco frecuente del flanco de dama","Un tipo de sacrificio de dama en el medio juego","Otra forma de nombrar al jaque mate forzado"]'::jsonb, null, 0, null, null, 'Lo ideal sería pasar el turno, pero las reglas obligan a jugar y cualquier jugada estropea la posición. Es la idea que sostiene casi todos los finales de peones.', null, null),
  ('fin_casillas_correspondientes', 'finales', 'opcion', 3, 1500, 1700, 'En finales de rey y peones más complejos, ¿qué son las «casillas correspondientes»?', '["Pares de casillas que los reyes deben ocuparse mutuamente","Las casillas en las que un peón puede llegar a coronar","Las casillas del mismo color a lo largo del tablero","Las casillas desde las que el rey todavía puede enrocar"]'::jsonb, null, 0, null, null, 'Es la oposición llevada más lejos: a cada casilla del rey atacante le corresponde una del defensor, y quien no llega a la suya cae en zugzwang. Se usa cuando la oposición directa no alcanza para decidir.', null, null),
  ('fin_pasado_protegido', 'finales', 'opcion', 2, 1200, 1200, '¿Por qué un «peón pasado protegido», defendido por otro peón propio, es especialmente fuerte?', '["Porque el rey no lo puede tomar, y avanza apoyado","Porque corona solo, sin necesidad de más jugadas","Porque no existe forma alguna de bloquearlo","Porque pasa a valer el doble que un peón normal"]'::jsonb, null, 0, null, null, 'El rey rival no puede capturarlo sin perder algo a cambio, así que queda clavado vigilándolo. En un final de peones, un pasado protegido suele valer la partida.', null, null),
  ('fin_pasados_conectados', 'finales', 'opcion', 2, 1200, 1200, '¿Por qué dos peones pasados y conectados son especialmente peligrosos en un final?', '["Porque se cubren entre ellos y no se frena a los dos","Porque pasan a valer el doble que un peón normal suelto","Porque no se los puede capturar de ninguna manera","Porque obligan al rival a enrocar de inmediato"]'::jsonb, null, 0, null, null, 'Uno defiende al otro mientras avanzan, así que el rey rival no puede pararlos solo: si se ocupa de uno, el otro sigue. Dos peones conectados en la sexta fila valen más que una torre.', null, null),
  ('fin_peon_torre_alfil_malo', 'finales', 'opcion', 3, 1640, 1700, 'Con un peón de la columna «a» o «h» y un alfil del color contrario a la casilla de coronación, ¿qué suele pasar?', '["Tablas si el rey defensor llega a esa esquina","Gana siempre quien tiene el peón, sin excepción","El alfil frena el peón sin ayuda de su rey","Tablas solo si quedan menos de tres peones"]'::jsonb, null, 0, null, null, 'El alfil no controla la casilla de coronación y el rey defensor se mete en la esquina: no hay forma de sacarlo. Es tablas aunque el atacante tenga varios peones de más, y por eso conviene saberlo antes de cambiar hacia ese final.', null, null),
  ('fin_rey_delante_peon', 'finales', 'opcion', 2, 1100, 1200, 'Como principio general en finales de rey y peón, ¿dónde conviene tener al propio rey respecto a su peón pasado?', '["Delante, abriéndole el camino a la coronación","Detrás del peón, empujándolo siempre desde atrás","Siempre en el flanco contrario del tablero","Da igual: el rey no influye en este final"]'::jsonb, null, 0, null, null, 'El rey va adelante despejando el camino y ganando la oposición; el peón lo sigue. Un peón que avanza solo, con el rey detrás, casi siempre se frena.', null, null),
  ('fin_teoricos_por_que', 'finales', 'opcion', 2, 1220, 1200, '¿Por qué conviene estudiar los «finales teóricos», las posiciones ya analizadas al detalle?', '["Porque tienen técnica exacta y resultado conocido","Porque son las únicas posiciones legales del juego","Porque solo aparecen en partidas de altísimo nivel","Porque estudiarlos reemplaza aprender táctica"]'::jsonb, null, 0, null, null, 'Su resultado ya está establecido y la técnica es conocida: se reconocen y se ejecutan, sin calcular bajo presión. Son pocas posiciones y aparecen una y otra vez.', null, null),
  ('fin_pasado_alejado', 'finales', 'opcion', 3, 1630, 1450, '¿Por qué un «peón pasado alejado» suele ser una ventaja decisiva en finales de peones?', '["Porque distrae al rey rival lejos de lo importante","Porque corona más rápido que cualquier otro peón","Porque la regla del cuadrado no se le aplica","Porque siempre está protegido por otro peón"]'::jsonb, null, 0, null, null, 'El rey defensor tiene que ir a buscarlo, y mientras tanto el otro flanco queda solo: el rey atacante se come todo lo que quedó sin defensa. Se gana ahí, no con el peón alejado.', null, null),
  ('fin_cuadrado_excepcion', 'finales', 'opcion', 3, 1630, 1450, 'La «regla del cuadrado» tiene una excepción importante: hay que agrandar el cuadrado si…', '["El peón no se movió y puede avanzar dos casillas","El rey defensor conserva más de un peón propio","Le toca mover al bando de las piezas blancas","El peón está en una de las columnas centrales"]'::jsonb, null, 0, null, null, 'Un peón en su casilla inicial recorre dos casillas de un salto, así que el cuadrado se cuenta desde la casilla a la que puede llegar, no desde donde está. Olvidarlo hace perder carreras que parecían ganadas.', null, null),
  ('fin_alfiles_mismo_color', 'finales', 'opcion', 3, 1400, 1450, 'A diferencia del final de alfiles de distinto color, en un final de alfiles del MISMO color con un peón de ventaja…', '["Suele ser bastante más fácil convertir la ventaja","También suelen terminar en tablas casi siempre igual","Los alfiles no se pueden capturar entre ellos","Es tablas si quedan menos de cuatro peones"]'::jsonb, null, 0, null, null, 'Los dos alfiles controlan las mismas casillas, así que no existe el bloqueo permanente que salva los finales de distinto color. Un peón de más suele alcanzar para ganar.', null, null),
  ('fin_torres_frecuentes', 'finales', 'opcion', 2, 1100, 1200, '¿Por qué se dice que los finales de torres son los más frecuentes en la práctica?', '["Porque las torres suelen ser las últimas en cambiarse","Porque el reglamento obliga a conservarlas al final","Porque alfiles y caballos se cambian por obligación","Porque las torres no coronan y por eso sobreviven"]'::jsonb, null, 0, null, null, 'Las torres entran en juego más tarde y se cambian después que las piezas menores, así que una parte enorme de las partidas llega a un final con torres. Es el final que más rinde estudiar.', null, null),
  ('fin_rey_lejos', 'finales', 'opcion', 1, 920, 950, 'Si el rey defensor queda muy lejos del flanco donde el rival tiene un peón pasado, ¿qué puede pasar?', '["Que el peón corone sin que el rey llegue a tiempo","Que el peón deje de ser peligroso automáticamente","Que solo el alfil pueda frenarlo, nunca el rey","Que se declaren tablas por fortaleza posicional"]'::jsonb, null, 0, null, null, 'Si el rey no entra en el cuadrado del peón, no lo alcanza y no hay nada que hacer. Por eso en los finales la posición del rey importa más que casi cualquier otra cosa.', null, null),
  ('fin_tiempo_vale_mas', 'finales', 'opcion', 1, 950, 1200, 'En un final ajustado, ¿por qué cada jugada suele valer mucho más que en la apertura?', '["Porque hay menos piezas y casi ningún margen de error","Porque en los finales el reloj corre más rápido por regla","Porque las piezas valen menos puntos en esta fase","Porque a esa altura ya no importa el orden de jugadas"]'::jsonb, null, 0, null, null, 'Con pocas piezas no hay con qué compensar una jugada perdida: un solo tiempo decide entre ganar, empatar o perder. En la apertura un tiempo se recupera; en el final, no.', null, null),
  ('fin_rey_pasivo_error', 'finales', 'opcion', 2, 1380, 950, '¿Cuál es un error común de jugadores principiantes en los finales?', '["Dejar el rey escondido en vez de activarlo","Activar demasiado pronto al propio rey","Cambiar demasiadas piezas antes de tiempo","Avanzar los peones con excesiva rapidez"]'::jsonb, null, 0, null, null, 'Después de toda una partida cuidando al rey, cuesta cambiar el chip: en el final ya casi no hay con qué atacarlo y tiene que salir a pelear como una pieza más. Un rey pasivo en un final es como jugar con una pieza menos.', null, null),
  ('fin_convertir_ventaja', 'finales', 'opcion', 2, 1320, 1200, '¿Qué significa «convertir una ventaja» en un final?', '["Llevar esa ventaja hasta la victoria, con técnica","Cambiar un tipo de ventaja por otra distinta","Entregar la ventaja para complicar la posición","Ofrecer tablas apenas se consigue alguna ventaja"]'::jsonb, null, 0, null, null, 'Tener ventaja no gana solo: hay que jugar el final con la técnica correcta para que el rival no se escape a tablas. La mayoría de los puntos que se pierden con ventaja se pierden acá.', null, null),
  ('est_controlar_centro', 'estrategia', 'opcion', 1, 620, 700, '¿Qué significa «controlar el centro» en ajedrez?', '["Dominar d4, d5, e4 y e5 con piezas y peones","Poner el propio rey en el centro del tablero","Mover primero los peones de las dos torres","Cambiar todas las piezas lo antes posible"]'::jsonb, null, 0, null, null, 'Desde el centro las piezas llegan a los dos flancos, así que quien lo domina mueve sus piezas de un lado al otro más rápido que el rival. Controlar no siempre es ocupar: también se controla a distancia.', null, null),
  ('est_columna_abierta', 'estrategia', 'opcion', 1, 770, 700, 'Una «columna abierta» es una columna…', '["Sin peones de ningún color, ideal para las torres","Con peones de los dos colores trabados entre sí","Aquella en la que está enrocado el propio rey","Que en realidad no existe en el reglamento"]'::jsonb, null, 0, null, null, 'Sin peones que la tapen, la torre ve la columna entera y se vuelve una pieza de verdad. Pelear por la columna abierta —y doblar torres en ella— es uno de los planes más comunes del medio juego.', null, null),
  ('est_desequilibrio_material', 'estrategia', 'opcion', 3, 1560, 1450, '¿A qué se llama «desequilibrio material» cuando se busca a propósito?', '["Cambiar piezas de distinto tipo pero valor parecido","Perder material sin ninguna razón que lo justifique","Jugar toda la partida entera sin usar la dama","Evitar por completo cualquier cambio de piezas"]'::jsonb, null, 0, null, null, 'Por ejemplo, dos piezas menores contra torre y peón: los puntos dan casi igual, pero la posición que sale favorece a un estilo de juego o al otro. Se busca a propósito para llevar la partida al terreno que uno conoce.', null, null),
  ('est_peones_doblados', 'estrategia', 'opcion', 1, 1010, 950, '¿Qué son los «peones doblados»?', '["Dos peones propios en la misma columna","Dos peones que avanzaron dos casillas a la vez","Dos peones que están en casillas del mismo color","Dos peones rivales capturados en una jugada"]'::jsonb, null, 0, null, null, 'Quedan uno delante del otro y no se pueden defender entre ellos, además de controlar menos casillas que si estuvieran separados. No siempre son malos: a cambio suelen abrir una columna para la torre.', null, null),
  ('est_peon_retrasado', 'estrategia', 'opcion', 2, 1160, 1200, '¿Qué es un «peón retrasado»?', '["Uno que quedó atrás y no puede avanzar seguro","Uno que todavía no se movió en toda la partida","Uno que va a coronar en la jugada siguiente","Uno que acaba de ser capturado al paso"]'::jsonb, null, 0, null, null, 'Sus vecinos ya avanzaron y no lo pueden proteger, y la casilla de adelante la controla el rival: queda clavado y es un blanco fijo, sobre todo si está en una columna abierta.', null, null),
  ('est_base_cadena', 'estrategia', 'opcion', 1, 1020, 1200, 'En una cadena de peones, ¿cuál es el punto más débil para atacar?', '["La base: el de más atrás, que nadie defiende","La punta de la cadena, que es la más avanzada","Siempre el peón que esté en una columna central","El peón que está en la columna del propio rey"]'::jsonb, null, 0, null, null, 'Todos los peones de la cadena están defendidos por el de atrás, menos el último: ese es el único que hay que atacar con piezas. Es el principio que ordena media estrategia de la Defensa Francesa.', null, null),
  ('est_ventaja_espacio', 'estrategia', 'opcion', 1, 1020, 950, '¿Qué significa tener «ventaja de espacio» en una posición?', '["Controlar más casillas y dejar al rival apretado","Tener más piezas en el tablero que el rival","Haber jugado más rápido que el rival hasta ahí","Tener el propio rey más cerca del centro"]'::jsonb, null, 0, null, null, 'Más casillas controladas es más lugar donde poner las piezas propias, y menos para las del rival, que empiezan a estorbarse entre ellas. Quien tiene menos espacio busca cambios; quien tiene más, los evita.', null, null),
  ('est_jugar_con_plan', 'estrategia', 'opcion', 2, 1160, 950, '¿Por qué se dice que hay que «jugar con un plan», en vez de mover pieza por pieza sin conexión?', '["Porque la posición misma sugiere qué hacer","Porque el reglamento obliga a anunciar un plan","Porque tener un plan garantiza ganar la partida","Porque sin un plan no se puede mover legalmente"]'::jsonb, null, 0, null, null, 'La estructura de peones, el espacio y las piezas que quedan dicen qué se puede intentar. Un plan conecta varias jugadas hacia lo mismo; sin él, cada jugada deshace lo que hizo la anterior.', null, null),
  ('est_peones_alma', 'estrategia', 'opcion', 1, 1090, 1200, 'La frase clásica «los peones son el alma del ajedrez», de Philidor, quiere decir que…', '["La estructura de peones decide qué planes hay","Los peones son las piezas más valiosas que hay","Sin peones en el tablero no se puede enrocar","Los peones deciden quién mueve primero"]'::jsonb, null, 0, null, null, 'Los peones casi no retroceden, así que la forma que toman es casi permanente y define el resto de la partida: dónde atacar, qué pieza sirve y cuál estorba. Por eso un avance de peón se piensa dos veces.', null, null),
  ('est_cambiar_alfil_malo', 'estrategia', 'opcion', 2, 1370, 1200, 'Si tienes un «alfil malo», encerrado por tus propios peones, ¿qué suele convenir?', '["Cambiarlo por una pieza rival en cuanto se pueda","No cambiarlo nunca, bajo ninguna circunstancia","Entregarlo de inmediato, sin pedir nada a cambio","Convertirlo en el centro del propio ataque"]'::jsonb, null, 0, null, null, 'Un alfil encerrado aporta poco y ocupa espacio propio. Cambiarlo por una pieza activa del rival —aunque sea «alfil por caballo»— suele mejorar la posición más que cualquier maniobra.', null, null),
  ('est_torre_septima', 'estrategia', 'opcion', 2, 1180, 1200, '¿Por qué una torre en la séptima fila suele ser muy fuerte?', '["Porque ataca los peones que aún no avanzaron","Porque en esa fila está a salvo de todo ataque","Porque le da jaque mate automático al rey","Porque estando ahí la torre pasa a valer el doble"]'::jsonb, null, 0, null, null, 'Los peones del rival siguen en su fila inicial, así que la torre los ataca todos de un tirón y de paso encierra al rey contra el borde. Dos torres en la séptima suelen valer más que una pieza de ventaja.', null, null)
